interface.definition:
a!localVariables(
  local!rotationalAskActualCompletedCount: sum(
    index(ri!rotationalAskEastActual,"traditionalComplete",0),
    index(ri!rotationalAskEastActual,"earlyCareerComplete",0),
    index(ri!rotationalAskWestActual,"traditionalComplete",0),
    index(ri!rotationalAskWestActual,"earlyCareerComplete",0)
  ),
  local!rotationalAskActualInProcessCount: sum(
    index(ri!rotationalAskEastActual,"traditionalInProcess",0),
    index(ri!rotationalAskEastActual,"earlyCareerInProcess",0),
    index(ri!rotationalAskWestActual,"traditionalInProcess",0),
    index(ri!rotationalAskWestActual,"earlyCareerInProcess",0)
  ),
  #"SYSTEM_SYSRULES_columnsLayout"(
    spacing: "NONE",
    columns: {
      #"SYSTEM_SYSRULES_columnLayout"(
        width: "WIDE",
        contents: {
          #"SYSTEM_SYSRULES_cardLayout"(
            showShadow: true,
            padding: "NONE",
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                padding: "EVEN_LESS",
                showBorder: false,
                style: ri!color,
                contents: {
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    alignVertical: "BOTTOM",
                    showDividers: true,
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(width: "NARROW"),
                      /*PLAN*/
                      #"SYSTEM_SYSRULES_columnLayout"(
                        width: "EXTRA_NARROW",
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            align: "CENTER",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Plan",
                              style: "STRONG"
                            )
                          )
                        }
                      ),
                      /*TOTAL ROTATIONALS VS ASK*/
                      #"SYSTEM_SYSRULES_columnLayout"(
                        width: "NARROW_PLUS",
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            align: "CENTER",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Total Rotationals vs Ask",
                              style: "STRONG"
                            )
                          ),
                          #"SYSTEM_SYSRULES_columnsLayout"(
                            columns: {
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "CENTER",
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: "Confirmed",
                                    style: "STRONG"
                                  )
                                )
                              ),
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "CENTER",
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: "In Process",
                                    style: "STRONG"
                                  )
                                )
                              ),
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "CENTER",
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: "Total",
                                    style: "STRONG"
                                  )
                                )
                              )
                            }
                          )
                        }
                      ),
                      /*VARIANCE*/
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            align: "CENTER",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Variance",
                              style: "STRONG"
                            )
                          )
                        }
                      ),
                    }
                  )
                }
              ),
              #"SYSTEM_SYSRULES_cardLayout"(
                showborder: false,
                padding: "EVEN_LESS",
                contents: #"SYSTEM_SYSRULES_columnsLayout"(
                  showDividers: true,
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      width: "NARROW",
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            style: "STRONG",
                            text: " Total Rotational Ask vs Actual"
                          )
                        )
                      }
                    ),
                    /*PLAN*/
                    #"SYSTEM_SYSRULES_columnLayout"(
                      width: "EXTRA_NARROW",
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          align: "CENTER",
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                              sum(
                                index(ri!rotationalAskEastPlan,"plan",{}),
                                index(ri!rotationalAskWestPlan,"plan",{})
                              )
                            ),
                            style: "STRONG"
                          )
                        )
                      }
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      width: "NARROW_PLUS",
                      contents: {
                        #"SYSTEM_SYSRULES_columnsLayout"(
                          showDividers: false,
                          spacing: "NONE",
                          columns: {
                            #"SYSTEM_SYSRULES_columnLayout"(
                              contents: {
                                #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "CENTER",
                                  labelPosition: "COLLAPSED",
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(local!rotationalAskActualCompletedCount),
                                    style: "STRONG"
                                  )
                                )
                              }
                            ),
                            #"SYSTEM_SYSRULES_columnLayout"(
                              contents: {
                                #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "CENTER",
                                  labelPosition: "COLLAPSED",
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(local!rotationalAskActualInProcessCount),
                                    style: "STRONG"
                                  )
                                )
                              }
                            ),
                            #"SYSTEM_SYSRULES_columnLayout"(
                              contents: {
                                #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  align: "CENTER",
                                  labelPosition: "COLLAPSED",
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                      sum(
                                        local!rotationalAskActualCompletedCount,
                                        local!rotationalAskActualInProcessCount
                                      )
                                    ),
                                    style: "STRONG"
                                  )
                                )
                              }
                            )
                          }
                        )
                      }
                    ),
                    /*VARIANCE*/
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          align: "CENTER",
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6636024"(
                              /*actual - planned*/
                              sum(
                                local!rotationalAskActualCompletedCount,
                                local!rotationalAskActualInProcessCount
                              ) - sum(
                                index(ri!rotationalAskEastPlan,"plan",{}),
                                index(ri!rotationalAskWestPlan,"plan",{})
                              )
                            ),
                            color: "NEGATIVE",
                            style: "STRONG"
                          )
                        )
                      }
                    )
                  }
                )
              )
            }
          )
        }
      ),
      #"SYSTEM_SYSRULES_columnLayout"()
    },
    showWhen: and(
      or(
        a!isNullOrEmpty(ri!typeFilter),
        ri!typeFilter = "Rotational"
      ),
      a!isNullOrEmpty(ri!regionFilter)
    )
  )
)
